  ["Route there on anything: road, flight, boat."] = "Маршрут куда угодно: по дороге, по воздуху, по морю.",
  ["Show the welcome at every login"] = "Показывать приветствие при каждом входе",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "Посидеть у костра вместе, поделиться им с группой, круг лагеря на вечер.",
  ["Switch on %s on the Suite page."] = "Включите %s на странице Suite.",
  ["Talk to a quest giver with the conversation on"] = "Поговорить с заказчиком задания при включенном диалоге",
  ["Talk to people without quest windows"] = "Говорить с людьми без окон заданий",
  ["Text"] = "Текст",
  ["The Gestures ring"] = "Круг Gestures",
  ["The Orbiter"] = "Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "Orbiter воспроизводит голоса Spoken для заданий, мест, книг и боссов и голос игры там, где у Spoken его нет.",
  ["The Orbiter plays the zone's story."] = "Orbiter воспроизводит историю зоны.",
  ["The campfire"] = "Костер",
  ["The hub: every app's settings, the Suite page, Help."] = "Центр: настройки каждого приложения, страница Suite, справка.",
  ["The land speaks"] = "Земля говорит",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "Земля рассказывает свои истории, пока вы идете (Orbiter со Spoken)",
  ["The screen for the view"] = "Экран для обзора",
  ["The search opens a page for anything."] = "Поиск открывает страницу для чего угодно.",
  ["The suite's button at the minimap"] = "Кнопка набора у миникарты",
  ["The suite's words"] = "Слова набора",
  ["The way there, by road, flight and boat"] = "Путь туда по дороге, по воздуху и по морю",
  ["The welcome stays away at login; the General page brings it back."] = 'Приветствие не показывается при входе; страница "Общие" возвращает его.',
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = 'Окно приветствия при каждом входе, пока вы не нажмете "Больше не показывать" в его углу (plan-launch-version D).',
  ["Try it"] = "Попробовать",
